@DgsData(parentType = "Author", field = "books")
public CompletableFuture<List<Book>> books(
    DgsDataFetchingEnvironment dfe,
    DataLoader<Long, List<Book>> bookDataLoader) {

    Author author = dfe.getSource();
    return bookDataLoader.load(author.getId());
}

@Component
public class BookDataLoader implements MappedBatchLoader<Long, List<Book>> {

    private final BookRepository bookRepository;

    public BookDataLoader(BookRepository bookRepository) {
        this.bookRepository = bookRepository;
    }

    @Override
    public CompletionStage<Map<Long, List<Book>>> load(Set<Long> authorIds) {
        return CompletableFuture.supplyAsync(() -> {
            List<Book> books = bookRepository.findByAuthorIdIn(authorIds);
            return books.stream()
                    .collect(Collectors.groupingBy(Book::getAuthorId));
        });
    }
}
